function demoMain(idx,label){
  var rows=[["a,1","b,2","c,3"],["x,10","y,20"],["p,5","q,6","r,7","s,8"]];
  var r=rows[idx%rows.length];
  var json=r.map(function(x){var p=x.split(",");return {name:p[0],val:+p[1]};});
  return "["+label+"] CSV->JSON: "+r.length+" rows => "+JSON.stringify(json);
}

